from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']

# Corrected lookup formulas using discovered Data layout:
# Data headers are in row 4: B=Code, C=Entity, D=Series code, E=Indicator name, F=Frequency, G=Units, H:L=2018:2022.
# Data records are rows 21:38; series codes are Data!D21:D38; year data is Data!H21:L38.
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            ws.cell(r,c).value = f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'

# Reassert downstream formulas.
for offset,r in enumerate(range(35,41)):
    ren_r=12+offset
    grid_r=19+offset
    base_r=26+offset
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(r,c).value=f'=({col}{ren_r}-{col}{grid_r})/{col}{base_r}*100'

stats={42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE'}
for r,fn in stats.items():
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(r,c).value=f'={fn}({col}$35:{col}$40)'
for r,pct in [(46,'0.25'),(47,'0.75')]:
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(r,c).value=f'=PERCENTILE({col}$35:{col}$40,{pct})'

for c in range(8,13):
    col=get_column_letter(c)
    ws.cell(50,c).value=f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'

wb.save(path)
print('Updated and saved corrected formulas to', path)
